function closePop(focus=false){if(!pop)return;const p=pop;pop=null;p.node.remove();p.trigger?.setAttribute('aria-expanded','false');if(focus&&p.trigger?.isConnected)p.trigger.focus()}
function positionPop(node,trigger){const b=trigger.getBoundingClientRect();const w=Math.min(node.offsetWidth,window.innerWidth-16),h=node.offsetHeight;node.dataset.side=b.bottom+h+8>innerHeight?'above':'below';node.style.width=w+'px';node.style.left=Math.max(8,Math.min(node.dataset.kind==='menu'?b.right-w:b.left,innerWidth-w-8))+'px';node.style.top=Math.max(8,b.bottom+h+8>innerHeight?b.top-h-6:b.bottom+6)+'px'}
