 root.querySelectorAll('details:not([data-v-disclosure]):not(.nav-group)').forEach(d=>{const summary=d.querySelector(':scope>summary');if(!summary)return;const open=d.open,body=document.createElement('div'),inner=document.createElement('div');body.className='v-collapse-body';inner.className='v-collapse-inner';body.id=uid('disclosure');while(summary.nextSibling)inner.append(summary.nextSibling);body.append(inner);d.append(body);d.open=true;d.dataset.vDisclosure='';summary.setAttribute('role','button');summary.setAttribute('aria-controls',body.id);disclosureState(d,open)});
