if(a==='message-feedback'){const article=b.closest('.v-message-assistant'),root=b.closest('[data-v-chat]'),id=b.dataset.messageId,key=b.dataset.feedback;const message=root?activeThread(root)?.messages.find(m=>m.id===id):null;if(root&&message?.state!=='completed')return;const previous=message?message.feedback:article.dataset.feedback;const apply=(value,reason=null,comment='')=>{if(message){message.feedback=value;message.feedbackReason=reason;message.feedbackComment=comment}article.dataset.feedback=value||'';article.querySelectorAll('[data-feedback]').forEach(el=>el.setAttribute('aria-pressed',el.dataset.feedback===value));article.querySelector('[data-message-feedback]').textContent=value==='up'?'已点赞':value==='down'?'已点踩 · 本地反馈':'已取消反馈';emit(b,'feedback',{messageId:id||null,value,reason,comment,simulated:true})};if(previous===key){apply(null);return}if(key==='up'){apply('up');return}const node=openPop(b,`<strong class="v-small">这条回答哪里需要改进？</strong><div class="v-feedback-reasons">${['内容不准确','没有帮助','表达不清晰','其他'].map(reason=>btn(reason,'','outline','',`data-reason="${reason}" aria-pressed="false"`)).join('')}</div><label class="v-field">补充说明（选填，最多 500 字）<textarea class="v-textarea" maxlength="500" data-feedback-comment></textarea></label><div class="v-row v-end" style="margin-top:12px">${btn('取消','','ghost','','data-feedback-cancel')}${btn('提交本地反馈','','primary','','data-feedback-submit')}</div>`,'dialog',320);node.setAttribute('aria-label','回答改进反馈');let reason=null;node.addEventListener('click',e=>{const choice=e.target.closest('[data-reason]');if(choice){reason=choice.dataset.reason;node.querySelectorAll('[data-reason]').forEach(x=>x.setAttribute('aria-pressed',x===choice))}if(e.target.closest('[data-feedback-cancel]'))closePop(true);if(e.target.closest('[data-feedback-submit]')){apply('down',reason,node.querySelector('textarea').value.slice(0,500));closePop(true)}});return}
